from commun_redaction import ROOT
import json,re
B=lambda kind,title,text:f'::: {kind}'+(' '+title if title else '')+'\n'+text+'\n:::\n'
SPEC={
21:(['Je choisis les centimètres pour un livre, les mètres pour une porte et les kilomètres pour un long trajet.','Je place le zéro de la règle au début du segment.','Si la règle est décalée, je retire la lecture du début à celle de la fin.','Avant de comparer ou de calculer, j’utilise la même unité.'],'Une règle dessinée à l’écran change de taille avec le zoom. Lis ses graduations ; pour tracer 8 cm, utilise ta vraie règle sur une feuille.','1 m = 100 cm ; 1 km = 1 000 m.\n\n1 m et 47 cm = 147 cm. La mesure garde toujours son unité.','La règle décalée'),
22:(['Je choisis une balance et je repère son unité : g ou kg.','Sur une balance à plateaux en équilibre, les masses des deux côtés sont égales.','Je réunis les masses marquées pour connaître celle de l’objet.','Pour comparer, je choisis une même unité : 1 kg = 1 000 g.'],'Un gros objet n’est pas forcément plus lourd qu’un petit : une boîte vide peut être plus légère qu’une petite pierre. Soupèse ou pèse pour vérifier.','1 kg = 1 000 g.\n\nUne gomme se mesure en grammes ; une personne en kilogrammes. À l’équilibre, les deux plateaux portent la même masse.','La balance en équilibre'),
23:(['Je sépare les euros et les centimes : cent centimes valent un euro.','J’écris deux chiffres pour les centimes : 05 pour cinq centimes.','Pour comparer ou additionner, je peux tout écrire en centimes.','Pour rendre la monnaie, je complète le prix jusqu’à la somme donnée.'],'Ne confonds pas 2,05 € et 2,50 € : cinq centimes et cinquante centimes n’ont pas la même valeur. Compte la valeur des pièces, pas seulement leur nombre.','1 € = 100 centimes.\n\n2,05 € = 2 euros et 5 centimes.\n\nPrix + monnaie rendue = somme donnée.','Payer avec les bonnes pièces'),
24:(['Je lis l’heure déjà commencée avec la petite aiguille.','Je lis les minutes avec la grande aiguille : 3 pour 15, 6 pour 30, 9 pour 45.','Je vérifie le moment de la journée ; l’après-midi, j’ajoute douze aux heures du cadran.','Pour dessiner, je place aussi la petite aiguille entre les deux heures.'],'La petite aiguille avance pendant toute l’heure. À 7 h 30, elle est au milieu entre 7 et 8 ; elle ne reste pas exactement sur 7.','1 h = 60 min ; un quart d’heure = 15 min ; une demi-heure = 30 min.\n\nGrande aiguille sur 3 : et quart ; sur 6 : et demie ; sur 9 : moins le quart de l’heure suivante.','Des quarts d’heure sur un cadran'),
25:(['Je repère le départ et la fin, qui sont des horaires.','Je compte jusqu’à l’heure entière suivante.','Je compte ensuite les minutes jusqu’à la fin.','Je réunis les morceaux de durée et je vérifie en avançant depuis le départ.'],'Une heure contient soixante minutes, pas cent. Soustraire les nombres 915 et 830 ne donne pas une durée en minutes.','1 h = 60 min ; 30 min = une demi-heure ; 15 min = un quart d’heure.\n\nUne durée mesure le temps écoulé. Un horaire repère un instant.','Passer par une heure entière'),
26:(['Je parcours le contour pour compter chaque côté et chaque sommet une fois.','Je pose le coin de l’équerre sur un angle pour vérifier s’il est droit.','Je compare l’ouverture des angles, pas la longueur des traits.','Pour reconnaître un carré, je vérifie quatre côtés égaux et quatre angles droits.'],'Tourner une figure ne change ni ses angles ni ses longueurs. Une figure à quatre côtés égaux doit aussi avoir quatre angles droits pour être un carré.','Rectangle : quatre angles droits. Carré : quatre angles droits et quatre côtés de même longueur.\n\nUn angle aigu est moins ouvert qu’un angle droit ; un angle obtus est plus ouvert.','Observer avec les bons instruments'),
27:(['Je pose le bord de la règle contre les points pour contrôler un alignement.','Pour trouver le milieu, je partage le segment en deux longueurs égales.','Pour un cercle, je garde la pointe du compas sur le centre et la même ouverture.','Je vérifie plusieurs points : ils doivent être à la même distance du centre.'],'Si la pointe du compas glisse ou si son ouverture change, le cercle demandé n’est pas obtenu. Le milieu est à la même distance des deux extrémités.','Points alignés : sur un même trait droit.\n\nMilieu : deux longueurs égales.\n\nCercle : un contour ; disque : le contour et son intérieur.','Le centre reste fixe'),
28:(['Je marque les sommets et les longueurs demandées.','Je trace un premier côté avec le zéro de la règle.','Je construis les angles droits avec l’équerre et je reporte les longueurs.','Je ferme la figure puis je contrôle tous les côtés et les angles avant de coder.'],'Un côté oblique peut appartenir à un carré. Sur quadrillage, compte les déplacements entre sommets ; sur papier uni, contrôle avec les instruments.','Règle : longueurs et traits droits. Équerre : angles droits. Compas : cercle à centre fixe.\n\nUne même marque sur deux côtés indique une même longueur, après vérification.','Construire puis contrôler'),
29:(['Je manipule l’objet et je le tourne pour voir ce qui est caché.','Je marque les faces déjà comptées pour n’en oublier aucune.','Je compte ensuite les arêtes et les sommets une seule fois.','Pour fabriquer un squelette, j’utilise une tige par arête et une boule de pâte par sommet.'],'Un dessin peut cacher des faces et des arêtes. Elles existent sur l’objet réel. Ne compte pas seulement les éléments que tu vois de face.','Cube : 6 faces carrées, 12 arêtes, 8 sommets.\n\nPavé : 6 faces rectangulaires, 12 arêtes, 8 sommets.\n\nPyramide à base carrée : 5 faces, 8 arêtes, 5 sommets.','Manipuler pour compter'),
30:(['Je marque le départ et la direction dans laquelle regarde le pion.','Je lis une instruction à la fois.','Tourner se fait sur place ; avancer se fait dans la direction du regard.','Je trace ou je suis le trajet, puis je vérifie la position et la direction finales.'],'La droite du pion dépend de la direction dans laquelle il regarde. « Tourne à droite » ne veut pas dire « va dans la case de droite du dessin ».','Un plan montre les lieux vus de dessus.\n\nTourner : changer la direction sans changer de case.\n\nAvancer : changer de case dans la direction du regard.','Départ, direction, déplacement')}
for code,(method,warning,key,figuretitle) in SPEC.items():
 d=next(ROOT.glob(f'{code:02}_*'));src=json.loads((d/'sources_locales/chapitre.json').read_text(encoding='utf-8'));steps='\n'.join(f'{i}. {s}' for i,s in enumerate(method,1))
 text='Titre: '+src['titre']+'\n<!-- optitab:1 -->\n'+B('objectifs','',src['objectif'])
 text+='\n## I. Je manipule et j’observe\n\n'+B('methode','Avec le matériel',src['manipulation'])+'\n[IMAGE_1]\n'
 text+='\n## II. Je comprends\n\n'+B('definition','Les repères','\n\n'.join(src['lecon']))
 if code==24:text+='\n[IMAGE_2]\n'
 if code in (27,28,29):text+=B('propriete','Des mots utiles',key)
 text+='\n## III. Je fais pas à pas\n\n'+B('methode',figuretitle,steps)+B('exemple','Un exemple expliqué',src['exemple'])
 text+='\n## IV. Je m’entraîne et je vérifie\n\n'+B('exemple','À toi de chercher',src['guide'])+B('resultat','Vérification',src['guide_reponse'])+B('attention','Le piège à éviter',warning)+B('retenir','',key)
 sheet='Titre: '+src['titre']+'\n<!-- optitab:1 -->\n'+B('retenir','',key)+'\n## I. Ma méthode\n\n'+B('methode','',steps)+'\n## II. Je vérifie\n\n'+B('exemple','',src['exemple'])+B('attention','',warning)
 (d/'cours_nouveau.txt').write_text(text,encoding='utf-8');(d/'fiche_nouvelle.txt').write_text(sheet,encoding='utf-8')
 print(code,'cours et synthèse préparés')
